return $input.all().flatMap((item, index) => {
const event = item.json;
if (event.status === 'cancelled') return [];
const entryPoints = Array.isArray(event.conferenceData?.entryPoints) ? event.conferenceData.entryPoints : [];
const text = `${event.location ?? ''} ${event.description ?? ''}`;
const candidates = [event.hangoutLink, ...entryPoints.filter(entry => entry?.entryPointType === 'video').map(entry => entry.uri), ...(text.match(/https:\/\/[^\s<>"]+/g) ?? [])];
const meetingLink = candidates.find(value => typeof value === 'string' && /^https:\/\/(?:meet\.google\.com|(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)*zoom\.us|teams\.(?:microsoft|live)\.com)(?::443)?\/[^\s<>"\\]+$/i.test(value));
if (!meetingLink) return [];
const occurrence = event.start?.dateTime ?? event.start?.date;
if (!event.id || !occurrence) throw new Error('Calendar event needs an ID and start time to prevent duplicate bots.');
return [{ json: {
  meetingLink,
  deduplicationKey: `google-calendar:${event.id}:${occurrence}`,
  customAttributes: {
    source: 'n8n_google_calendar',
    calendar_event_id: event.id,
    event_start: occurrence,
    event_title: event.summary ?? ''
  }
}, pairedItem: { item: index } }];
});
